import{_ as t,a,c as i,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 26 The best art critics","description":"学习 一般现在时与习惯，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 26 The best art critics","description":"学习 一般现在时与习惯，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 一般现在时与习惯，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 25 Do the English speak English?","link":"/life/english/new-concept/book-2/unit-02/lesson-025"},"next":{"text":"第二册：实践与进步 · Lesson 27 A wet night","link":"/life/english/new-concept/book-2/unit-02/lesson-027"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 25 Do the English speak English?","link":"/life/english/new-concept/book-2/unit-02/lesson-025"},"next":{"text":"第二册：实践与进步 · Lesson 27 A wet night","link":"/life/english/new-concept/book-2/unit-02/lesson-027"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-02/lesson-026.md","filePath":"life/english/new-concept/book-2/unit-02/lesson-026.md"}'),s={name:"life/english/new-concept/book-2/unit-02/lesson-026.md"};function o(l,e,r,h,d,c){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-lesson-26-the-best-art-critics" tabindex="-1">第二册：实践与进步 · Lesson 26 The best art critics <a class="header-anchor" href="#第二册-实践与进步-·-lesson-26-the-best-art-critics" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 26 The best art critics&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>面对抽象画，不同观众作出不同判断；练习经常性的评价和此刻正在观察的动作。本课的语言观察是：understand 和 like 表状态时通常不用进行时；look at 是可持续的动作，可以用 is looking。表达个人审美不要把主观意见写成客观结论。完成学习后，请描述自己偏爱的艺术风格，再描述今天正在观看的一件不同作品。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>painting</td><td>/ˈpeɪntɪŋ/</td><td>n.</td><td>画作</td><td>an abstract painting</td></tr><tr><td>artist</td><td>/ˈɑːtɪst/</td><td>n.</td><td>艺术家</td><td>a young artist</td></tr><tr><td>judge</td><td>/dʒʌdʒ/</td><td>v.</td><td>评判</td><td>judge fairly</td></tr><tr><td>colour</td><td>/ˈkʌlə/</td><td>n.</td><td>颜色</td><td>a bright colour</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>look at — 看某物，侧重动作</li><li>in my opinion — 在我看来，标记个人观点</li></ul><h2 id="语法讲解-一般现在时与习惯" tabindex="-1">语法讲解：一般现在时与习惯 <a class="header-anchor" href="#语法讲解-一般现在时与习惯" aria-label="Permalink to &quot;语法讲解：一般现在时与习惯&quot;">​</a></h2><p>一般现在时可以描述习惯、规律和当前相对稳定的状态。第三人称单数主语的实义动词通常加 -s；使用 does 或 does not 后，动词回到原形。频率副词常放在实义动词前、be 动词后，但句首句尾也有特定用法。正在发生的临时动作通常另用进行时，不能仅因句中出现 today 就自动选一般现在时或现在进行时。本课应用：understand 和 like 表状态时通常不用进行时；look at 是可持续的动作，可以用 is looking。表达个人审美不要把主观意见写成客观结论。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>My sister likes paintings with strong colours.</p></blockquote><p>我妹妹喜欢色彩强烈的画。</p><p>likes 表稳定偏好，paintings 是泛指复数，with strong colours 为后置修饰语。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>She is liking this style 在一般偏好语境下不自然；常用 She likes this style。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>对照 likes 与 is studying，突出习惯和临时活动；black-and-white 连作一组。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>My sister likes paintings with strong colours. Today she is studying a black-and-white drawing. She says its simple lines are beautiful.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>描述自己偏爱的艺术风格，再描述今天正在观看的一件不同作品。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：likes 表稳定偏好，paintings 是泛指复数，with strong colours 为后置修饰语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：She is liking this style 在一般偏好语境下不自然；常用 She likes this style。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 like：My sister ___ bright colours.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> likes</p><p><strong>解析：</strong> 一般现在时第三人称单数。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>今天她观察的作品有鲜艳颜色吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> No. It is a black-and-white drawing.</p><p><strong>解析：</strong> 日常偏好不排除欣赏另一种风格。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将“我正在看画，但还不理解它”译成英语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> I am looking at the painting, but I do not understand it yet.</p><p><strong>解析：</strong> look at 用进行时，状态动词 understand 通常用简单时态。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：一般现在时与习惯。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-025">上一课</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-02/lesson-027">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const k=t(s,[["render",o]]);export{u as __pageData,k as default};
